CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); INSERT OR IGNORE INTO settings (key, value) VALUES ('points_enabled', '1'); CREATE TABLE IF NOT EXISTS run_meta ( run_id TEXT PRIMARY KEY REFERENCES game_runs(id), player_id TEXT NOT NULL REFERENCES players(id), game_id TEXT NOT NULL REFERENCES games(id), night_key TEXT NOT NULL, week TEXT NOT NULL, started_ms INTEGER NOT NULL, finished_ms INTEGER, band INTEGER, counted INTEGER NOT NULL DEFAULT 0, points INTEGER NOT NULL DEFAULT 0, replay_ms INTEGER, flags TEXT ); CREATE UNIQUE INDEX IF NOT EXISTS uq_run_counted ON run_meta (player_id, game_id, night_key) WHERE counted = 1; CREATE INDEX IF NOT EXISTS idx_run_meta_player ON run_meta (player_id, night_key); CREATE INDEX IF NOT EXISTS idx_run_meta_week ON run_meta (week, game_id, player_id); CREATE INDEX IF NOT EXISTS idx_run_meta_open ON run_meta (finished_ms, started_ms); INSERT OR IGNORE INTO schema_migrations (version, name) VALUES ('0003', 'runs');
